import type { JSX, ParentComponent } from "solid-js";

export interface SandboxBoxProps extends JSX.HTMLAttributes<HTMLDivElement> {
	class?: string;
}

// Use Parent Component to create a component that can contain children
export const SandboxBox: ParentComponent<SandboxBoxProps> = (props) => {
	return (
		<div
			{...props}
			class={`img-dropdown-box m-2 p-4 flex flex-col ${props.class}`}
		>
			{props.children}
		</div>
	);
};
